INSERT INTO INT_SERVERFUNCTION (ID, NAME, DESCRIPTION, TYPE, CODE, JDBC_ID, PUBLIC_EXECUTION, CRON_EXPRESSION, CRON_INPUT_JSON, CREATED_BY) VALUES (186, 'playground_versoes', 'Playground: lista versoes de HTML do estudo — param id.', 'SQL', 'SELECT ID, CRIADO_EM, CHAR_LENGTH(HTML) AS TAMANHO FROM PLAYGROUND_VERSAO WHERE PLAYGROUND_ID = {{id}} ORDER BY ID DESC LIMIT 50', NULL, FALSE, NULL, NULL, 'sarah@mitralab.io');
